export let CONFIG={currentCycle:'2026-2027',historyYears:[2023,2024,2025,2026]};
export function configure(config){if(!/^20\d{2}-20\d{2}$/.test(config.currentCycle)||!Array.isArray(config.historyYears)||!config.historyYears.every(Number.isInteger))throw new Error('Invalid archive configuration');CONFIG=config}
export const REGIONS={US:'美国',CA:'加拿大',HK:'香港',SG:'新加坡',CN:'中国大陆',TW:'台湾',MO:'澳门',JP:'日本',FR:'法国',DE:'德国',ES:'西班牙',VN:'越南',UY:'乌拉圭',IR:'伊朗',UK:'英国',EU:'欧洲',AU:'澳大利亚',KR:'韩国',OTHER:'其他地区',UNKNOWN:'未核验'};
export const JOBS={faculty:'教职 · 轨道未核验',tt:'终身轨教职',non_tt:'非终身轨教职',postdoc:'博士后',industry:'企业',government:'政府 / 公共机构',research:'研究机构',unknown:'岗位类别未核验',on_market:'当季求职中'};
export const BG={all:'全部背景',cn_national:'中国公民 · 公开确认',cn_heritage:'华裔 · 本人公开自述',ug_cn:'本科在中国大陆',ug_hk:'本科在香港',ug_tw:'本科在台湾',ug_other:'本科在其他地区',ug_unknown:'本科地区未核验'};
export const JOB_COLORS={faculty:'#208b78',tt:'#165c4f',non_tt:'#8eb9ac',postdoc:'#8a94ce',industry:'#d49d56',government:'#617c94',research:'#afbcc4',unknown:'#dfe4e8',on_market:'#829ea0'};
export function backgroundMatches(r,bg){const u=r.undergraduate?.region;if(bg==='all')return true;if(bg==='cn_national')return r.identity?.chinese_national?.value==='yes';if(bg==='cn_heritage')return r.identity?.chinese_heritage?.value==='yes';if(bg==='ug_unknown')return !u||u==='UNKNOWN';if(bg==='ug_other')return !!u&&!['CN','HK','TW','UNKNOWN'].includes(u);return u===({ug_cn:'CN',ug_hk:'HK',ug_tw:'TW'}[bg]);}
export function filterRecords(records,f={}){const words=(f.q||'').toLowerCase().trim().split(/\s+/).filter(Boolean);return records.filter(r=>{if(f.period==='current'&&r.market_cycle!==CONFIG.currentCycle)return false;if(f.period==='history'&&!(r.status==='placed'&&CONFIG.historyYears.includes(r.placement_year)&&r.market_cycle!==CONFIG.currentCycle))return false;if(/^20\d{2}$/.test(f.period||'')&&!(r.status==='placed'&&r.placement_year===Number(f.period)))return false;if(f.track==='marketing_unclassified'&&!(r.tracks.includes('marketing')&&!r.tracks.some(t=>['qm','cb'].includes(t))))return false;if(f.track&& !['all','marketing_unclassified'].includes(f.track)&&!r.tracks.includes(f.track))return false;if(f.origin&&f.origin!=='all'&&r.origin!==f.origin)return false;if(f.school&&f.school!=='all'&&r.school!==f.school)return false;if(f.job&&f.job!=='all'&&r.job_kind!==f.job)return false;if(f.destination&&f.destination!=='all'&&r.destination_region!==f.destination)return false;if(f.topic&&f.topic!=='all'&&!r.topics.includes(f.topic))return false;if(f.method&&f.method!=='all'&&!r.methods.includes(f.method))return false;if(f.background&&!backgroundMatches(r,f.background))return false;const text=[r.name,r.school,r.program,r.destination,r.role,r.jmp,...(r.aliases||[]),...r.fields,...r.topics,...r.methods].filter(Boolean).join(' ').toLowerCase();return words.every(w=>text.includes(w))})}
export function summarize(records){const historical=records.filter(r=>['placed','outcome_unknown'].includes(r.status));const known=historical.filter(r=>r.destination);const faculty=known.filter(r=>['faculty','tt','non_tt'].includes(r.job_kind));return {count:records.length,schools:new Set(records.map(r=>r.school)).size,historical:historical.length,known:known.length,unknown:historical.length-known.length,faculty:faculty.length,postdoc:known.filter(r=>r.job_kind==='postdoc').length,onMarket:records.filter(r=>r.status==='on_market').length,facultyShare:known.length?faculty.length/known.length:null,identityKnown:records.filter(r=>r.identity?.chinese_national?.value==='yes'||r.identity?.chinese_heritage?.value==='yes').length}}
export function tally(records,fn){const m=new Map();for(const r of records){const values=fn(r);for(const k of new Set(Array.isArray(values)?values:[values]))if(k)m.set(k,(m.get(k)||0)+1)}return [...m].sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0]))}
export function csvCell(v){let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}
